public class Solution {
    // SYMPTOM: wrong counts and survivors
    public static int removeAll(java.util.ArrayList<String> list, String target) {
        int removed = 0;
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i).equals(target)) {
                list.remove(i);
            }
        }
        return removed;
    }
}

